  1	package br.com.loja;
  2	
  3	import static org.assertj.core.api.Assertions.assertThat;
  4	
  5	import java.math.BigDecimal;
  6	import java.net.URI;
  7	import java.net.http.HttpClient;
  8	import java.net.http.HttpRequest;
  9	import java.net.http.HttpResponse;
 10	import java.util.concurrent.atomic.AtomicReference;
 11	
 12	import org.junit.jupiter.api.Test;
 13	import org.springframework.beans.factory.annotation.Autowired;
 14	import org.springframework.boot.test.context.SpringBootTest;
 15	import org.springframework.boot.test.context.TestConfiguration;
 16	import org.springframework.boot.test.web.server.LocalServerPort;
 17	import org.springframework.context.annotation.Bean;
 18	import org.springframework.context.annotation.Primary;
 19	import org.springframework.jdbc.core.simple.JdbcClient;
 20	
 21	import br.com.loja.shipping.CarrierGateway;
 22	import tools.jackson.databind.JsonNode;
 23	import tools.jackson.databind.json.JsonMapper;
 24	
 25	@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT, properties = {
 26	        "spring.datasource.url=jdbc:h2:mem:loja;MODE=PostgreSQL;DB_CLOSE_DELAY=-1",
 27	        "spring.datasource.username=sa", "spring.datasource.password="})
 28	class LojaIntegrationTest {
 29	
 30	    static final AtomicReference<Object> CARRIER = new AtomicReference<>();
 31	
 32	    @TestConfiguration
 33	    static class Config {
 34	        @Bean
 35	        @Primary
 36	        CarrierGateway stubCarrier() {
 37	            return (zip, grams, service) -> {
 38	                Object r = CARRIER.get();
 39	                if (r instanceof CarrierGateway.CarrierQuote q) {
 40	                    return q;
 41	                }
 42	                if (r instanceof CarrierGateway.ZipNotServedException e) {
 43	                    throw e;
 44	                }
 45	                throw new CarrierGateway.CarrierDownException("down", null);
 46	            };
 47	        }
 48	    }
 49	
 50	    @LocalServerPort int port;
 51	    @Autowired JdbcClient jdbc;
 52	    final HttpClient http = HttpClient.newHttpClient();
 53	    final JsonMapper json = JsonMapper.builder().build();
 54	
 55	    record Res(int status, JsonNode body) {
 56	    }
 57	
 58	    Res call(String method, String path, String body) throws Exception {
 59	        return send(method, path, body);
 60	    }
 61	
 62	    Res send(String method, String path, String body) throws Exception {
 63	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create("http://localhost:" + port + path))
 64	                .header("Content-Type", "application/json");
 65	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 66	        HttpResponse<String> r = http.send(b.build(), HttpResponse.BodyHandlers.ofString());
 67	        return new Res(r.statusCode(), json.readTree(r.body()));
 68	    }
 69	
 70	    void carrier(int cents, int hours) {
 71	        CARRIER.set(new CarrierGateway.CarrierQuote(BigDecimal.valueOf(cents, 2), (hours + 23) / 24));
 72	    }
 73	
 74	    String cart(String cpf, String items, String shipping, String coupon, String payment, int inst, String tier,
 75	                String region) {
 76	        return """
 77	                {"customer":{"cpf":"%s","email":"a@b.com"},"items":[%s],"zipCode":"01310100","region":"%s",
 78	                 "shippingMethod":"%s",%s"paymentMethod":"%s","installments":%d,"clubTier":"%s"}"""
 79	                .formatted(cpf, items, region, shipping, coupon == null ? "" : "\"coupon\":\"" + coupon + "\",",
 80	                        payment, inst, tier);
 81	    }
 82	
 83	    void assertSummary(JsonNode s, String subtotal, String coupon, String freight, int days, String insurance,
 84	                       String adjustment, String total, int inst, String instAmount, String credit, boolean gift) {
 85	        assertThat(s.get("productsSubtotal").decimalValue()).isEqualByComparingTo(subtotal);
 86	        assertThat(s.get("couponDiscount").decimalValue()).isEqualByComparingTo(coupon);
 87	        assertThat(s.get("shippingCost").decimalValue()).isEqualByComparingTo(freight);
 88	        assertThat(s.get("deliveryDays").intValue()).isEqualTo(days);
 89	        assertThat(s.get("insurance").decimalValue()).isEqualByComparingTo(insurance);
 90	        assertThat(s.get("paymentAdjustment").decimalValue()).isEqualByComparingTo(adjustment);
 91	        assertThat(s.get("finalTotal").decimalValue()).isEqualByComparingTo(total);
 92	        assertThat(s.get("installments").intValue()).isEqualTo(inst);
 93	        assertThat(s.get("installmentAmount").decimalValue()).isEqualByComparingTo(instAmount);
 94	        assertThat(s.get("nextPurchaseCredit").decimalValue()).isEqualByComparingTo(credit);
 95	        assertThat(s.get("gift").booleanValue()).isEqualTo(gift);
 96	    }
 97	
 98	    static final String CAM2_TEN1 = "{\"sku\":\"CAM-001\",\"quantity\":2},{\"sku\":\"TEN-001\",\"quantity\":1}";
 99	
100	    @Test
101	    void financeExamples() throws Exception {
102	        carrier(3310, 41);
103	        Res r = call("POST", "/checkout/summary", cart("10000000001", CAM2_TEN1, "EXPRESS", "WELCOME10", "PIX", 1, "BRONZE", "NORTH"));
104	        assertThat(r.status()).isEqualTo(200);
105	        assertSummary(r.body(), "409.70", "40.97", "33.10", 5, "10.24", "0.00", "412.07", 1, "412.07", "0.00", false);
106	
107	        carrier(1560, 168);
108	        r = call("POST", "/checkout/summary", cart("10000000002", CAM2_TEN1, "ECONOMY", null, "CREDIT_CARD", 6, "SILVER", "MIDWEST"));
109	        assertSummary(r.body(), "409.70", "0.00", "15.60", 7, "6.15", "30.55", "462.00", 6, "77.00", "8.19", false);
110	
111	        r = call("POST", "/checkout/summary", cart("10000000003", "{\"sku\":\"FON-001\",\"quantity\":2}", "COURIER", "MINUS50", "BANK_SLIP", 1, "GOLD", "NORTHEAST"));
112	        assertSummary(r.body(), "399.80", "50.00", "18.00", 0, "8.00", "3.49", "379.29", 1, "379.29", "19.99", false);
113	
114	        r = call("POST", "/checkout/summary", cart("10000000004", "{\"sku\":\"MEI-001\",\"quantity\":7},{\"sku\":\"CAM-001\",\"quantity\":2}", "STORE_PICKUP", "BUY3PAY2", "CREDIT_CARD", 3, "SILVER", "SOUTH"));
115	        assertSummary(r.body(), "299.10", "39.80", "0.00", 1, "2.99", "0.00", "262.29", 3, "87.43", "5.98", false);
116	
117	        carrier(2475, 30);
118	        r = call("POST", "/checkout/summary", cart("10000000005", "{\"sku\":\"CAM-001\",\"quantity\":3}", "EXPRESS", "BUY3PAY2", "PIX", 1, "BRONZE", "SOUTHEAST"));
119	        assertSummary(r.body(), "239.70", "71.91", "24.75", 2, "2.40", "0.00", "194.94", 1, "194.94", "0.00", false);
120	
121	        carrier(2210, 150);
122	        r = call("POST", "/checkout/summary", cart("10000000006", "{\"sku\":\"MEI-001\",\"quantity\":1}", "ECONOMY", "FREESHIPPING", "BANK_SLIP", 1, "BRONZE", "SOUTH"));
123	        assertSummary(r.body(), "19.90", "5.97", "22.10", 7, "0.20", "3.49", "39.72", 1, "39.72", "0.00", false);
124	
125	        carrier(5080, 49);
126	        r = call("POST", "/checkout/summary", cart("10000000007", "{\"sku\":\"JAQ-001\",\"quantity\":3},{\"sku\":\"TEN-001\",\"quantity\":1}", "EXPRESS", null, "PIX", 1, "GOLD", "NORTH"));
127	        assertSummary(r.body(), "1419.60", "0.00", "0.00", 6, "30.00", "-72.48", "1377.12", 1, "1377.12", "70.98", true);
128	
129	        r = call("POST", "/checkout/summary", cart("10000000008", "{\"sku\":\"CAM-001\",\"quantity\":1}", "STORE_PICKUP", "FREESHIPPING", "PIX", 1, "SILVER", "SOUTHEAST"));
130	        assertThat(r.status()).isEqualTo(422);
131	        assertThat(r.body().get("error").asString()).isEqualTo("COUPON_NOT_APPLICABLE");
132	
133	        CARRIER.set(new CarrierGateway.ZipNotServedException());
134	        r = call("POST", "/checkout/summary", cart("10000000010", "{\"sku\":\"TEN-001\",\"quantity\":1}", "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH"));
135	        assertThat(r.body().get("error").asString()).isEqualTo("SHIPPING_METHOD_UNAVAILABLE");
136	
137	        CARRIER.set("down");
138	        r = call("POST", "/checkout/summary", cart("10000000010", "{\"sku\":\"TEN-001\",\"quantity\":1}", "ECONOMY", null, "PIX", 1, "BRONZE", "NORTH"));
139	        assertThat(r.status()).isEqualTo(503);
140	        assertThat(r.body().get("error").asString()).isEqualTo("CARRIER_UNAVAILABLE");
141	    }
