143	    @Test
144	    void emptyCouponIsInvalid() throws Exception {
145	        Res r = call("POST", "/checkout/summary", cart("10000000011", "{\"sku\":\"CAM-001\",\"quantity\":1}", "STORE_PICKUP", "", "PIX", 1, "BRONZE", "SOUTH"));
146	        assertThat(r.body().get("error").asString()).isEqualTo("INVALID_COUPON");
147	    }
148	
149	    @Test
150	    void orderLifecycleAndIdempotentPayment() throws Exception {
151	        String cpf = "20000000001";
152	        String body = cart(cpf, "{\"sku\":\"MOC-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "GOLD", "SOUTH");
153	        Res created = call("POST", "/orders", body);
154	        assertThat(created.status()).isEqualTo(201);
155	        String id = created.body().get("id").asString();
156	        assertThat(created.body().get("status").asString()).isEqualTo("AWAITING_PAYMENT");
157	        assertThat(call("GET", "/customers/" + cpf, null).body().get("creditBalance").decimalValue())
158	                .isEqualByComparingTo("0");
159	
160	        // outro cliente tenta comprar a última mochila: ainda há estoque, estoque só baixa no pagamento
161	        Res second = call("POST", "/orders", cart("20000000002", "{\"sku\":\"MOC-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "BRONZE", "SOUTH"));
162	        String id2 = second.body().get("id").asString();
163	
164	        String created1 = created.body().get("createdAt").asString();
165	        String pay = "{\"transactionId\":\"TX-1\",\"paidAt\":\"" + created1 + "\"}";
166	        Res p = call("POST", "/orders/" + id + "/payment", pay);
167	        assertThat(p.status()).isEqualTo(200);
168	        assertThat(p.body().get("status").asString()).isEqualTo("PAID");
169	        Res again = call("POST", "/orders/" + id + "/payment", pay);
170	        assertThat(again.body()).isEqualTo(p.body());
171	        assertThat(call("POST", "/orders/" + id + "/payment", pay.replace("TX-1", "TX-2")).status()).isEqualTo(409);
172	
173	        assertThat(call("GET", "/products/MOC-001", null).body().get("stock").intValue()).isZero();
174	        assertThat(call("GET", "/customers/" + cpf, null).body().get("creditBalance").decimalValue())
175	                .isEqualByComparingTo("8.00");
176	        assertThat(call("GET", "/customers/" + cpf + "/notifications", null).body()).hasSize(1);
177	
178	        Res noStock = call("POST", "/orders/" + id2 + "/payment", pay.replace("TX-1", "TX-9"));
179	        assertThat(noStock.status()).isEqualTo(409);
180	        assertThat(noStock.body().get("error").asString()).isEqualTo("INSUFFICIENT_STOCK");
181	        assertThat(call("POST", "/orders/" + id2 + "/payment", pay.replace("TX-1", "TX-9")).body())
182	                .isEqualTo(noStock.body());
183	        assertThat(call("GET", "/orders/" + id2, null).body().get("status").asString()).isEqualTo("CANCELLED");
184	
185	        assertThat(call("POST", "/orders/" + id + "/delivery", null).status()).isEqualTo(409);
186	        assertThat(call("POST", "/orders/" + id + "/shipment", "{}").status()).isEqualTo(422);
187	        Res shipped = call("POST", "/orders/" + id + "/shipment", "{\"trackingCode\":\"BR1\"}");
188	        assertThat(shipped.body().get("trackingCode").asString()).isEqualTo("BR1");
189	        assertThat(call("POST", "/orders/" + id + "/cancellation", null).status()).isEqualTo(409);
190	        assertThat(call("POST", "/orders/" + id + "/delivery", null).body().get("status").asString())
191	                .isEqualTo("DELIVERED");
192	        assertThat(call("GET", "/orders/nope", null).status()).isEqualTo(404);
193	    }
194	
195	    @Test
196	    void paidOrderCancellationRestoresStockAndCredit() throws Exception {
197	        String cpf = "30000000001";
198	        Res created = call("POST", "/orders", cart(cpf, "{\"sku\":\"MEI-001\",\"quantity\":10}", "STORE_PICKUP", null, "PIX", 1, "SILVER", "SOUTH"));
199	        String id = created.body().get("id").asString();
200	        call("POST", "/orders/" + id + "/payment", "{\"transactionId\":\"T\",\"paidAt\":\"" + created.body().get("createdAt").asString() + "\"}");
201	        int stockPaid = call("GET", "/products/MEI-001", null).body().get("stock").intValue();
202	        assertThat(call("POST", "/orders/" + id + "/cancellation", null).status()).isEqualTo(200);
203	        assertThat(call("GET", "/products/MEI-001", null).body().get("stock").intValue()).isEqualTo(stockPaid + 10);
204	        assertThat(call("GET", "/customers/" + cpf, null).body().get("creditBalance").decimalValue())
205	                .isEqualByComparingTo("0");
206	        assertThat(call("GET", "/customers/" + cpf + "/notifications", null).body()).hasSize(2);
207	        Res read = call("POST", "/notifications/1/read", null);
208	        assertThat(read.body().get("status").asString()).isEqualTo("READ");
209	    }
210	
211	    @Test
212	    void paymentExactly48hAcceptedAndAfterExpires() throws Exception {
213	        Res created = call("POST", "/orders", cart("40000000001", "{\"sku\":\"CAM-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "BRONZE", "SOUTH"));
214	        String id = created.body().get("id").asString();
215	        java.time.Instant at = java.time.Instant.parse(created.body().get("createdAt").asString());
216	        Res late = call("POST", "/orders/" + id + "/payment", "{\"transactionId\":\"T\",\"paidAt\":\"" + at.plusSeconds(48 * 3600 + 1) + "\"}");
217	        assertThat(late.status()).isEqualTo(409);
218	        assertThat(late.body().get("error").asString()).isEqualTo("ORDER_EXPIRED");
219	
220	        Res c2 = call("POST", "/orders", cart("40000000001", "{\"sku\":\"CAM-001\",\"quantity\":1}", "STORE_PICKUP", null, "PIX", 1, "BRONZE", "SOUTH"));
221	        String id2 = c2.body().get("id").asString();
222	        java.time.Instant at2 = java.time.Instant.parse(c2.body().get("createdAt").asString());
223	        Res ok = call("POST", "/orders/" + id2 + "/payment", "{\"transactionId\":\"T2\",\"paidAt\":\"" + at2.plusSeconds(48 * 3600) + "\"}");
224	        assertThat(ok.status()).isEqualTo(200);
225	    }
226	}
