  3	import static org.assertj.core.api.Assertions.assertThat;
  4	import static org.assertj.core.api.Assertions.assertThatThrownBy;
  5	
  6	import java.net.InetSocketAddress;
  7	import java.nio.charset.StandardCharsets;
  8	
  9	import org.junit.jupiter.api.AfterEach;
 10	import org.junit.jupiter.api.Test;
 11	
 12	import com.sun.net.httpserver.HttpServer;
 13	
 14	import br.com.loja.shipping.CarrierGateway;
 15	import br.com.loja.shipping.TransLogGateway;
 16	
 17	class TransLogGatewayTest {
 18	
 19	    HttpServer server;
 20	
 21	    String start(int status, String body, long delayMs) throws Exception {
 22	        server = HttpServer.create(new InetSocketAddress("localhost", 0), 0);
 23	        server.createContext("/v2/quote", ex -> {
 24	            try {
 25	                Thread.sleep(delayMs);
 26	            } catch (InterruptedException ignored) {
 27	            }
 28	            byte[] bytes = body.getBytes(StandardCharsets.UTF_8);
 29	            ex.sendResponseHeaders(status, bytes.length);
 30	            ex.getResponseBody().write(bytes);
 31	            ex.close();
 32	        });
 33	        server.start();
 34	        return "http://localhost:" + server.getAddress().getPort();
 35	    }
 36	
 37	    @AfterEach
 38	    void stop() {
 39	        if (server != null) {
 40	            server.stop(0);
 41	        }
 42	    }
 43	
 44	    @Test
 45	    void parsesQuote() throws Exception {
 46	        var gw = new TransLogGateway(start(200, "{\"price_cents\":3310,\"eta_hours\":41}", 0));
 47	        var q = gw.quote("01310100", 1800, "EXP");
 48	        assertThat(q.price()).isEqualByComparingTo("33.10");
 49	        assertThat(q.days()).isEqualTo(2);
 50	    }
 51	
 52	    @Test
 53	    void zipNotServed() throws Exception {
 54	        var gw = new TransLogGateway(start(200, "{\"error\":\"ZIP_NOT_SERVED\"}", 0));
 55	        assertThatThrownBy(() -> gw.quote("01310100", 1800, "STD"))
 56	                .isInstanceOf(CarrierGateway.ZipNotServedException.class);
 57	    }
 58	
 59	    @Test
 60	    void otherResponsesMeanDown() throws Exception {
 61	        var gw = new TransLogGateway(start(500, "oops", 0));
 62	        assertThatThrownBy(() -> gw.quote("01310100", 1800, "STD"))
 63	                .isInstanceOf(CarrierGateway.CarrierDownException.class);
 64	    }
 65	
 66	    @Test
 67	    void timeoutMeansDown() throws Exception {
 68	        var gw = new TransLogGateway(start(200, "{\"price_cents\":1,\"eta_hours\":1}", 2500));
 69	        assertThatThrownBy(() -> gw.quote("01310100", 1800, "STD"))
 70	                .isInstanceOf(CarrierGateway.CarrierDownException.class);
 71	    }
 72	}
