 71	/** Porta para uma transportadora externa. Trocar de transportadora = nova implementação desta interface. */
 72	public interface CarrierGateway {
 73	
 74	    /**
 75	     * @throws ZipNotServedException quando a transportadora não atende o CEP
 76	     * @throws CarrierDownException  quando ela não responde direito
 77	     */
 78	    CarrierQuote quote(String zipCode, long weightGrams, String service);
 79	
 80	    record CarrierQuote(BigDecimal price, int days) {
 81	    }
 82	
 83	    class ZipNotServedException extends RuntimeException {
 84	    }
 85	
 86	    class CarrierDownException extends RuntimeException {
 87	        public CarrierDownException(String message, Throwable cause) {
 88	            super(message, cause);
 89	        }
 90	    }
 91	}
