    35	    /**
    36	     * Baixa o estoque de todos os itens ou de nenhum. Trava as linhas em ordem de SKU (evita deadlock entre
    37	     * duas máquinas) e só baixa se todas têm saldo; o UPDATE ainda protege com "stock >= quantidade".
    38	     * Precisa rodar dentro de uma transação.
    39	     */
    40	    public boolean reserve(List<OrderItem> items) {
    41	        List<OrderItem> sorted = items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList();
    42	        for (OrderItem item : sorted) {
    43	            Integer stock = jdbc.sql("SELECT stock FROM products WHERE sku = :sku FOR UPDATE")
    44	                    .param("sku", item.sku()).query(Integer.class).single();
    45	            if (stock < item.quantity()) {
    46	                return false;
    47	            }
    48	        }
    49	        for (OrderItem item : sorted) {
    50	            int updated = jdbc.sql("UPDATE products SET stock = stock - :q WHERE sku = :sku AND stock >= :q")
    51	                    .param("q", item.quantity()).param("sku", item.sku()).update();
    52	            if (updated != 1) {
    53	                throw new IllegalStateException("Estoque mudou durante a reserva de " + item.sku());
    54	            }
    55	        }
    56	        return true;
    57	    }
    58	
    59	    public void release(List<OrderItem> items) {
    60	        for (OrderItem item : items.stream().sorted(Comparator.comparing(OrderItem::sku)).toList()) {
    61	            jdbc.sql("UPDATE products SET stock = stock + :q WHERE sku = :sku")
    62	                    .param("q", item.quantity()).param("sku", item.sku()).update();
    63	        }
    64	    }
